procedure:public.advance_reconciliation_.source_code:
declare
  result public.reconciliation_cursors;
begin
  if p_cursor_value is null
    or p_last_ledger_sequence <= 0
    or p_last_ledger_closed_at is null
    or p_correlation_id is null then
    raise exception 'complete reconciliation cursor evidence is required'
      using errcode = '22004';
  end if;

  insert into public.reconciliation_cursors (
    network, stream_name, cursor_value, last_ledger_sequence,
    last_ledger_closed_at, correlation_id
  ) values (
    p_network, p_stream_name, p_cursor_value, p_last_ledger_sequence,
    p_last_ledger_closed_at, p_correlation_id
  )
  on conflict (network, stream_name) do update
  set cursor_value = excluded.cursor_value,
      last_ledger_sequence = excluded.last_ledger_sequence,
      last_ledger_closed_at = excluded.last_ledger_closed_at,
      correlation_id = excluded.correlation_id
  returning * into result;

  return result;
end;

procedure:public.claim_financial_idempot.source_code:
declare
  claimed public.idempotency_keys;
begin
  insert into public.idempotency_keys (
    organization_id, program_id, scope, idempotency_key,
    payload_hash, operation_type, correlation_id
  ) values (
    p_organization_id, p_program_id, p_scope, p_idempotency_key,
    p_payload_hash, p_operation_type, p_correlation_id
  )
  on conflict (organization_id, scope, idempotency_key) do nothing
  returning * into claimed;

  if claimed.id is null then
    select * into claimed
    from public.idempotency_keys
    where organization_id = p_organization_id
      and scope = p_scope
      and idempotency_key = p_idempotency_key
    for update;

    if claimed.payload_hash is distinct from p_payload_hash
      or claimed.operation_type is distinct from p_operation_type
      or claimed.program_id is distinct from p_program_id then
      raise exception 'idempotency key payload hash conflict'
        using errcode = '23514';
    end if;

    update public.idempotency_keys
    set last_seen_at = now()
    where id = claimed.id
    returning * into claimed;
  end if;

  return claimed;
end;

procedure:public.complete_wallet_proof(u.source_code:
declare
  target public.wallets;
  result public.wallets;
  activate_binding boolean;
begin
  if p_signature_digest !~ '^[0-9a-f]{64}$' or p_verified_by is null then
    raise exception 'invalid wallet proof evidence' using errcode = '22023';
  end if;
  select * into strict target from public.wallets where id = p_wallet_id for update;
  if target.verification_status <> 'challenge_issued'
    or target.proof_challenge_expires_at <= now()
    or target.proof_challenge_digest <> p_challenge_digest then
    raise exception 'wallet proof challenge is stale or does not match'
      using errcode = '42501';
  end if;
  activate_binding := not exists (
    select 1 from public.wallets wallet
    where wallet.owner_type = target.owner_type
      and wallet.owner_id = target.owner_id
      and wallet.network = target.network
      and wallet.purpose = target.purpose
      and wallet.is_active
  );
  update public.wallets
  set verification_status = 'verified',
      proof_signature_digest = p_signature_digest,
      verified_at = now(),
      verified_by = p_verified_by,
      is_active = activate_binding
  where id = p_wallet_id
  returning * into result;
  return result;
end;

