      using errcode = '42501';
  end if;

  update public.retention_records
  set disposition_status = 'disposed', disposed_at = now(),
      disposed_by = p_actor_id,
      disposition_reference = btrim(p_disposition_reference),
      correlation_id = p_correlation_id
